const refreshWABroadcast = `-- name: RefreshWABroadcast :one
UPDATE wa_broadcasts b
SET sent = (SELECT count(*) FROM wa_broadcast_recipients r WHERE r.broadcast_id = b.id AND r.status = 'sent'),
    failed = (SELECT count(*) FROM wa_broadcast_recipients r WHERE r.broadcast_id = b.id AND r.status = 'failed'),
    status = CASE WHEN EXISTS (SELECT 1 FROM wa_broadcast_recipients r WHERE r.broadcast_id = b.id AND r.status = 'queued')
                  THEN 'sending' ELSE 'done' END,
    finished_at = CASE WHEN EXISTS (SELECT 1 FROM wa_broadcast_recipients r WHERE r.broadcast_id = b.id AND r.status = 'queued')
                       THEN NULL ELSE now() END
WHERE b.id = $1
RETURNING id, name, template_name, language, variables, audience, status, total, sent, failed, created_by, created_at, finished_at
`

func (q *Queries) RefreshWABroadcast(ctx context.Context, id uuid.UUID) (WaBroadcast, error) {
	row := q.db.QueryRow(ctx, refreshWABroadcast, id)
	var i WaBroadcast
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.TemplateName,
		&i.Language,
		&i.Variables,
		&i.Audience,
		&i.Status,
		&i.Total,
		&i.Sent,
		&i.Failed,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.FinishedAt,
	)
	return i, err
}

