const updateWAMessageStatus = `-- name: UpdateWAMessageStatus :one
UPDATE wa_messages
SET status = $1::text, error = CASE WHEN $2::text <> '' THEN $2::text ELSE error END
WHERE wa_message_id = $3
  AND ($1::text = 'failed'
       OR (CASE status WHEN 'queued' THEN 0 WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2 WHEN 'read' THEN 3 ELSE 9 END)
          < (CASE $1::text WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2 WHEN 'read' THEN 3 ELSE 0 END))
RETURNING contact_id
`

type UpdateWAMessageStatusParams struct {
	Status      string  `json:"status"`
	Error       string  `json:"error"`
	WaMessageID *string `json:"wa_message_id"`
}

// Delivery receipts only move forward (sent → delivered → read); failures always win.
func (q *Queries) UpdateWAMessageStatus(ctx context.Context, arg UpdateWAMessageStatusParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, updateWAMessageStatus, arg.Status, arg.Error, arg.WaMessageID)
	var contact_id uuid.UUID
	err := row.Scan(&contact_id)
	return contact_id, err
}

const upsertWAContact = `-- name: UpsertWAContact :one

INSERT INTO wa_contacts (wa_id, profile_name, lead_id, student_id)
VALUES ($1, $2, $3, $4)
ON CONFLICT (wa_id) DO UPDATE
SET profile_name = CASE WHEN EXCLUDED.profile_name <> '' THEN EXCLUDED.profile_name ELSE wa_contacts.profile_name END,
    lead_id = COALESCE(wa_contacts.lead_id, EXCLUDED.lead_id),
    student_id = COALESCE(wa_contacts.student_id, EXCLUDED.student_id)
RETURNING id, wa_id, profile_name, lead_id, student_id, last_inbound_at, last_message_at, unread, created_at
`

type UpsertWAContactParams struct {
	WaID        string     `json:"wa_id"`
	ProfileName string     `json:"profile_name"`
	LeadID      *uuid.UUID `json:"lead_id"`
	StudentID   *uuid.UUID `json:"student_id"`
}

// ───────────── Contacts ─────────────
func (q *Queries) UpsertWAContact(ctx context.Context, arg UpsertWAContactParams) (WaContact, error) {
	row := q.db.QueryRow(ctx, upsertWAContact,
		arg.WaID,
		arg.ProfileName,
		arg.LeadID,
		arg.StudentID,
	)
	var i WaContact
	err := row.Scan(
		&i.ID,
		&i.WaID,
		&i.ProfileName,
		&i.LeadID,
		&i.StudentID,
		&i.LastInboundAt,
		&i.LastMessageAt,
		&i.Unread,
		&i.CreatedAt,
	)
	return i, err
}

const upsertWATemplate = `-- name: UpsertWATemplate :exec

INSERT INTO wa_templates (name, language, category, status, body, variables, synced_at)
VALUES ($1, $2, $3, $4, $5, $6, now())
ON CONFLICT (name, language) DO UPDATE
SET category = EXCLUDED.category, status = EXCLUDED.status, body = EXCLUDED.body, variables = EXCLUDED.variables, synced_at = now()
`

type UpsertWATemplateParams struct {
	Name      string `json:"name"`
	Language  string `json:"language"`
	Category  string `json:"category"`
	Status    string `json:"status"`
	Body      string `json:"body"`
	Variables int32  `json:"variables"`
}

// ───────────── Templates & quick replies ─────────────
func (q *Queries) UpsertWATemplate(ctx context.Context, arg UpsertWATemplateParams) error {
	_, err := q.db.Exec(ctx, upsertWATemplate,
		arg.Name,
		arg.Language,
		arg.Category,
		arg.Status,
		arg.Body,
		arg.Variables,
	)
	return err
}
